from pathlib import Path
files={}
files['src/pages/manager/DashboardPage.jsx']=r'''import {Link} from 'react-router-dom';
import {Warehouse,Layers,Users,Clock,Wallet,CalendarCheck,Package,Wrench,ArrowRight} from 'lucide-react';
import {useManagerData,capacity,money,customerName} from '@/lib/managerDemoStore';
import {today,assignedFacility} from '@/mocks/managerData';
import {Screen,Panel,Card,CardContent,Status,Table,OpenLink,Meter,Button} from '@/components/manager/ManagerUI';
export default function DashboardPage(){const data=useManagerData(),c=capacity(data);const occupied=data.units.filter(u=>u.status==='OCCUPIED').length;const kpis=[['Self-Storage occupancy',`${data.units.length?Math.round(occupied/data.units.length*100):0}%`,`${occupied} of ${data.units.length} units occupied`,Warehouse],['Managed capacity utilization',`${c.max?Math.round(c.used/c.max*100):0}%`,`${c.used} of ${c.max} m³ in use`,Layers],['Active rentals',data.rentals.filter(r=>r.status==='ACTIVE').length,'Currently active at this facility',Users],['Overdue rentals',data.rentals.filter(r=>r.status==='OVERDUE').length,'Review checkout and outstanding dues',Clock],['Revenue',money(data.payments.filter(r=>r.status==='PAID').reduce((s,r)=>s+r.amount,0)),'Collected rental payments in demo ledger',Wallet],['Pending reservations',data.reservations.filter(r=>r.status==='PENDING').length,'Awaiting your review',CalendarCheck],['Inventory items',data.items.filter(r=>r.status==='IN_STORAGE').length,'Registered item records in storage',Package],['Maintenance issues',data.maintenance.filter(r=>r.status!=='RESOLVED').length,'Open or in progress',Wrench]];const operations=data.tasks.filter(r=>r.date===today);return <Screen title="Your facility, at a glance" code="P046" description={`${assignedFacility.name} · A focused view of capacity, customers and today’s operations.`} action={<Button asChild variant="orange"><Link to="/manager/operations">Open operations<ArrowRight size={16}/></Link></Button>}><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{kpis.map(([label,value,hint,Icon])=><Card key={label} className="manager-kpi"><CardContent><div className="flex items-center justify-between"><p className="text-xs font-semibold text-slate-500">{label}</p><span className="kpi-icon"><Icon size={17}/></span></div><p className="mt-4 text-2xl font-bold">{value}</p><p className="mt-2 text-[11px] leading-5 text-slate-500">{hint}</p></CardContent></Card>)}</div><div className="grid gap-6 xl:grid-cols-[1.5fr_1fr]"><Panel title="Today’s operations" subtitle={`${today} · ${operations.length} tasks`} action={<OpenLink to="/manager/operations">All operations</OpenLink>}><Table label="Today's operations" rows={operations.slice(0,5)} columns={[{key:'type',label:'Operation',render:r=><OpenLink to={`/manager/operations/${r.id}`}>{r.type.replaceAll('_',' ')}</OpenLink>},{key:'resource',label:'Resource'},{key:'status',label:'Status',render:r=><Status value={r.status}/>} ]}/></Panel><Panel title="Capacity overview" subtitle="Operational shelf capacity and customer allocations"><div className="space-y-7"><Meter label="Private units" used={occupied} max={data.units.length} unit="units"/><Meter label="Managed shelf volume" used={c.used} max={c.max}/><Meter label="Allocated customer capacity" used={c.allocated} max={c.max}/></div></Panel></div><Panel title="Recent reservations" action={<OpenLink to="/manager/reservations">Review reservations</OpenLink>}><Table rows={data.reservations.slice(0,5)} columns={[{key:'id',label:'Reservation',render:r=><OpenLink to={`/manager/reservations/${r.id}`}>{r.id}</OpenLink>},{key:'customer',label:'Customer',render:r=>customerName(data,r.customerId)},{key:'service',label:'Service',render:r=>r.service.replaceAll('_',' ')},{key:'start',label:'Move-in'},{key:'status',label:'Status',render:r=><Status value={r.status}/>} ]}/></Panel><div className="grid gap-6 lg:grid-cols-2"><Panel title="Pending approvals"><div className="space-y-3">{[['reservations','Reservations'],['extensions','Extensions'],['refunds','Refunds']].map(([key,label])=><Link key={key} to={`/manager/${key}`} className="flex justify-between rounded-xl bg-[#f1f6ef] p-4 text-sm"><b>{label}</b><span>{data[key].filter(r=>r.status==='PENDING').length} pending →</span></Link>)}</div></Panel><Panel title="Operational alerts"><ul className="space-y-3 text-sm">{data.rentals.filter(r=>r.status==='OVERDUE').map(r=><li key={r.id} className="rounded-xl bg-orange-50 p-4"><OpenLink to="/manager/reports/rentals">{r.id}: overdue since {r.end}</OpenLink></li>)}{data.maintenance.filter(r=>r.status!=='RESOLVED').map(r=><li key={r.id} className="rounded-xl bg-[#f1f6ef] p-4"><OpenLink to={`/manager/maintenance/${r.id}`}>{r.issue}</OpenLink></li>)}{!data.maintenance.length&&!data.rentals.length&&<li>No alerts available.</li>}</ul></Panel></div></Screen>;}
'''
files['src/pages/manager/ReservationsPage.jsx']=r'''import {useState} from 'react';
import {useParams} from 'react-router-dom';
import {useManagerData,customerName,unitCode,availability,decide} from '@/lib/managerDemoStore';
import {assignedFacility,managerPermissions} from '@/mocks/managerData';
import {Screen,Panel,Table,OpenLink,Status,Filters,Field,Select,Input,Details,Timeline,Decision,NotFound} from '@/components/manager/ManagerUI';
export default function ReservationsPage(){const data=useManagerData(),{id}=useParams();const [status,setStatus]=useState(''),[service,setService]=useState(''),[date,setDate]=useState('');if(id){const row=data.reservations.find(r=>r.id===id);if(!row)return <Screen title="Reservation" code="P013 / P014"><NotFound/></Screen>;const available=availability(data,row);return <Screen title={row.id} code="P013 / P014" description="Review the exact storage selection and approve or reject this request." action={<OpenLink to="/manager/reservations">All reservations</OpenLink>}><div className="grid gap-6 lg:grid-cols-[1.4fr_1fr]"><Panel title="Reservation details"><Details values={[["Customer",<OpenLink to={`/manager/customers/${row.customerId}`}>{customerName(data,row.customerId)}</OpenLink>],['Service type',row.service.replaceAll('_',' ')],['Facility',assignedFacility.name],['Status',<Status value={row.status}/>],['Move-in date',row.start],['End date',row.end],['Created date',row.created],...(row.service==='SELF_STORAGE'?[['Selected Storage Unit',<OpenLink to={`/manager/storage-units/${row.unitId}`}>{unitCode(data,row.unitId)}</OpenLink>],['Unit size',row.size]]:[['Requested allocated_capacity_m3',`${row.allocated_capacity_m3} m³`],['Placement','Shelf placement is determined during inbound operations.']]) ]}/></Panel><Panel title="Review decision" subtitle="Approval is local to this demo; no contract or payment is created."><p className={`mb-5 rounded-xl p-4 text-sm ${available?'bg-emerald-50':'bg-orange-50'}`}>{available?'Availability check passed.':'Selected unit / managed capacity is currently unavailable.'}</p><Decision status={row.status} available={available} allowed={managerPermissions.approveReservations} onDecision={(decision,reason)=>decide('reservations',id,decision,reason)}/></Panel></div><Panel title="Status timeline"><Timeline entries={row.timeline}/></Panel></Screen>;}
const rows=data.reservations.filter(r=>(!status||r.status===status)&&(!service||r.service===service)&&(!date||r.start===date));return <Screen title="Reservations" code="P013 / P014" description="Review new requests for private units and managed capacity at your assigned facility."><Panel title="Facility reservations" subtitle={`${rows.length} matching records`}><Filters><Field label="Status"><Select label="Reservation status" value={status} onChange={setStatus} options={[["","All statuses"],'PENDING','APPROVED','REJECTED']}/></Field><Field label="Service type"><Select label="Reservation service" value={service} onChange={setService} options={[["","All services"],'SELF_STORAGE','MANAGED_INVENTORY']}/></Field><Field label="Move-in date"><Input aria-label="Reservation move-in date" type="date" value={date} onChange={e=>setDate(e.target.value)}/></Field></Filters><Table rows={rows} columns={[{key:'id',label:'Reservation ID',render:r=><OpenLink to={`/manager/reservations/${r.id}`}>{r.id}</OpenLink>},{key:'customer',label:'Customer',render:r=>customerName(data,r.customerId)},{key:'service',label:'Service type',render:r=>r.service.replaceAll('_',' ')},{key:'facility',label:'Facility',render:()=>assignedFacility.id},{key:'dates',label:'Dates',render:r=><>{r.start}<br/>{r.end}</>},{key:'status',label:'Status',render:r=><Status value={r.status}/>},{key:'created',label:'Created'}]}/></Panel></Screen>;}
'''
files['src/pages/manager/CustomersPage.jsx']=r'''import {useState} from 'react';
import {useParams} from 'react-router-dom';
import {useManagerData,verifyCustomer,money,managerDemoEnabled,unitCode} from '@/lib/managerDemoStore';
import {managerPermissions} from '@/mocks/managerData';
import {Screen,Panel,Details,Status,Table,OpenLink,Field,Input,Select,Textarea,Button,NotFound,Message,useAction} from '@/components/manager/ManagerUI';
export default function CustomersPage(){const data=useManagerData(),{id}=useParams(),[search,setSearch]=useState(''),[verification,setVerification]=useState('VERIFIED'),[note,setNote]=useState(''),action=useAction();if(!id)return <Screen title="Customers" code="P010 / P011" description="Profiles and rental activity for customers of your assigned facility."><Panel title="Customer directory"><Field label="Search customer"><Input aria-label="Search customer" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Name, email or customer ID"/></Field><div className="mt-5"><Table rows={data.customers.filter(r=>[r.name,r.email,r.id].some(v=>v.toLowerCase().includes(search.toLowerCase())))} columns={[{key:'name',label:'Customer',render:r=><OpenLink to={`/manager/customers/${r.id}`}>{r.name}</OpenLink>},{key:'id',label:'ID'},{key:'email',label:'Email'},{key:'phone',label:'Phone'},{key:'verification',label:'Verification',render:r=><Status value={r.verification}/>},{key:'rentals',label:'Active rentals',render:r=>data.rentals.filter(x=>x.customerId===r.id&&x.status==='ACTIVE').length}]}/></div></Panel></Screen>;
 const row=data.customers.find(r=>r.id===id);if(!row)return <Screen title="Customer" code="P010 / P011"><NotFound/></Screen>;const rentals=data.rentals.filter(r=>r.customerId===id),payments=data.payments.filter(r=>r.customerId===id),tickets=data.support.filter(r=>r.customerId===id);const cols=[{key:'id',label:'Rental'},{key:'service',label:'Service',render:r=>r.service.replaceAll('_',' ')},{key:'resource',label:'Unit / capacity',render:r=>r.service==='SELF_STORAGE'?unitCode(data,r.unitId):`${r.allocated_capacity_m3} m³`},{key:'period',label:'Period',render:r=>`${r.start} → ${r.end}`},{key:'status',label:'Status',render:r=><Status value={r.status}/>}];return <Screen title={row.name} code="P010 / P011" description={row.id} action={<OpenLink to="/manager/customers">All customers</OpenLink>}><div className="grid gap-6 lg:grid-cols-2"><Panel title="Customer profile"><Details values={[["Full name",row.name],['Email',row.email],['Phone',row.phone],['Address',row.address],['Verification',<Status value={row.verification}/>],['Customer since',row.created],['Review notes',row.verificationNote||'Not reviewed']]}/></Panel><Panel title="Verification review" subtitle="Demo status review only. Identity documents are not stored here."><form className="space-y-4" onSubmit={e=>{e.preventDefault();action.run(()=>verifyCustomer(id,verification,note));}}><Field label="Verification decision"><Select label="Verification decision" value={verification} onChange={setVerification} options={['VERIFIED','REJECTED']}/></Field><Field label="Review notes"><Textarea aria-label="Verification review notes" required value={note} onChange={e=>setNote(e.target.value)}/></Field><Message {...action}/><Button disabled={!managerDemoEnabled||!managerPermissions.verifyCustomers}>Save verification</Button></form></Panel></div><Panel title="Active rentals"><Table rows={rentals.filter(r=>r.status==='ACTIVE')} columns={cols}/></Panel><Panel title="Rental history"><Table rows={rentals} columns={cols}/></Panel><Panel title="Payment summary" subtitle={`Collected: ${money(payments.filter(p=>p.status==='PAID').reduce((s,p)=>s+p.amount,0))} · Outstanding: ${money(payments.filter(p=>p.status==='PENDING').reduce((s,p)=>s+p.amount,0))}`}><Table rows={payments} columns={[{key:'id',label:'Payment'},{key:'description',label:'Description'},{key:'date',label:'Date'},{key:'amount',label:'Amount',render:r=>money(r.amount)},{key:'status',label:'Status',render:r=><Status value={r.status}/>} ]}/></Panel><Panel title="Support history"><Table rows={tickets} columns={[{key:'id',label:'Ticket',render:r=><OpenLink to={`/manager/support/${r.id}`}>{r.id}</OpenLink>},{key:'subject',label:'Subject'},{key:'category',label:'Category'},{key:'status',label:'Status',render:r=><Status value={r.status}/>} ]}/></Panel></Screen>;}
'''
files['src/pages/manager/StorageUnitsPage.jsx']=r'''import {useState} from 'react';
import {useParams} from 'react-router-dom';
import {useManagerData,saveUnit,money,managerDemoEnabled} from '@/lib/managerDemoStore';
import {assignedFacility,managerPermissions} from '@/mocks/managerData';
import {Screen,Panel,Details,Status,Table,OpenLink,Field,Input,Select,Button,Dialog,NotFound,Message,Filters,useAction} from '@/components/manager/ManagerUI';
function UnitForm({unit,onClose}){const [values,setValues]=useState(unit?{code:unit.code,size:unit.size,status:unit.status,price:unit.price,pricingReference:unit.pricingReference}:{code:'',size:'Small',status:'AVAILABLE',price:750000,pricingReference:'SELF-S-2026'}),action=useAction();const set=(key,value)=>setValues(v=>({...v,[key]:value}));return <Dialog title={unit?'Edit Storage Unit':'Create Storage Unit'} onClose={onClose}><form className="space-y-4" onSubmit={e=>{e.preventDefault();if(action.run(()=>saveUnit(unit?.id,values)))onClose();}}><Field label="Unit code"><Input aria-label="Unit code" required value={values.code} onChange={e=>set('code',e.target.value)}/></Field><Field label="Size"><Select label="Unit size" value={values.size} onChange={v=>set('size',v)} disabled={!!unit?.rentalId} options={['Small','Medium','Large']}/></Field><Field label="Status"><Select label="Unit status" value={values.status} onChange={v=>set('status',v)} disabled={!!unit?.rentalId} options={unit?.rentalId?['OCCUPIED']:['AVAILABLE','MAINTENANCE','UNAVAILABLE']}/></Field><Field label="Monthly reference price (VND)"><Input aria-label="Unit price" type="number" min="1" step="1" required value={values.price} onChange={e=>set('price',e.target.value)}/></Field><Field label="Pricing reference"><Input aria-label="Pricing reference" required value={values.pricingReference} onChange={e=>set('pricingReference',e.target.value)}/></Field><p className="text-xs text-slate-500">Facility: {assignedFacility.name}. Existing rental charges are preserved.</p><Message {...action}/><Button disabled={!managerDemoEnabled||!managerPermissions.manageUnits}>Save unit</Button></form></Dialog>;}
export default function StorageUnitsPage(){const data=useManagerData(),{id}=useParams(),[edit,setEdit]=useState(false),[size,setSize]=useState(''),[status,setStatus]=useState('');const unit=data.units.find(r=>r.id===id);if(id&&!unit)return <Screen title="Storage Unit" code="P008"><NotFound/></Screen>;const rows=data.units.filter(r=>(!size||r.size===size)&&(!status||r.status===status));return <Screen title={id?`Unit ${unit.code}`:'Storage units'} code="P008" description="Private Self-Storage units, their pricing references and operational availability." action={<Button variant="orange" disabled={!managerDemoEnabled||!managerPermissions.manageUnits} onClick={()=>setEdit(true)}>{id?'Edit unit':'Create unit'}</Button>}>{id?<><OpenLink to="/manager/storage-units">All units</OpenLink><Panel title="Unit details"><Details values={[["Unit code",unit.code],['Service','SELF STORAGE'],['Size',unit.size],['Status',<Status value={unit.status}/>],['Pricing reference',unit.pricingReference],['Monthly reference price',money(unit.price)],['Facility',assignedFacility.name],['Current rental',unit.rentalId||'No current rental'],['Maintenance state',<Status value={unit.maintenance}/>]]}/></Panel><Panel title="Related maintenance"><Table rows={data.maintenance.filter(r=>r.resourceId===id)} columns={[{key:'issue',label:'Issue',render:r=><OpenLink to={`/manager/maintenance/${r.id}`}>{r.issue}</OpenLink>},{key:'priority',label:'Priority',render:r=><Status value={r.priority}/>},{key:'status',label:'Status',render:r=><Status value={r.status}/>} ]}/></Panel></>:<Panel title="Facility unit directory"><Filters><Field label="Size"><Select label="Filter unit size" value={size} onChange={setSize} options={[["","All sizes"],'Small','Medium','Large']}/></Field><Field label="Status"><Select label="Filter unit status" value={status} onChange={setStatus} options={[["","All statuses"],'AVAILABLE','OCCUPIED','MAINTENANCE','UNAVAILABLE']}/></Field></Filters><Table rows={rows} columns={[{key:'code',label:'Unit',render:r=><OpenLink to={`/manager/storage-units/${r.id}`}>{r.code}</OpenLink>},{key:'size',label:'Size'},{key:'status',label:'Status',render:r=><Status value={r.status}/>},{key:'price',label:'Monthly reference',render:r=>money(r.price)},{key:'pricingReference',label:'Pricing reference'},{key:'facilityId',label:'Facility'},{key:'rentalId',label:'Current rental'},{key:'maintenance',label:'Maintenance',render:r=><Status value={r.maintenance}/>} ]}/></Panel>}{edit&&<UnitForm unit={id?unit:null} onClose={()=>setEdit(false)}/>}</Screen>;}
'''
for name,content in files.items():
 p=Path(name);p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content,encoding='utf-8')
